const LottieControls = withCSS(
    function LottieControls(props: LottieControlsProps) {
        const isReverse = props.direction === "-1"
        const [isPlaying, setIsPlaying] = React.useState(false)
        const [isLooping, setIsLooping] = React.useState(Boolean(props.loop))
        const [progress, setProgress] = React.useState(0)

        function getDotLottie(): DotLottiePlayer | undefined {
            return props.dotLottie ?? undefined
        }

        function getProgressFromDotLottie(dotLottie?: DotLottiePlayer) {
            if (!dotLottie?.totalFrames) return 0

            return (dotLottie.currentFrame / dotLottie.totalFrames) * 100
        }

        React.useEffect(() => {
            setIsPlaying(false)
            setIsLooping(Boolean(props.loop))
            setProgress(0)
        }, [props.src])

        React.useEffect(() => {
            setIsLooping(Boolean(props.loop))
        }, [props.loop])

        React.useEffect(() => {
            let frameId = 0

            // This seems to be the most reliable way to sync the state of the lottie player with the controls.
            // Subscribing to event listeners ends up missing some events (e.g. autoplay doesn’t seem to fire `play`),
            // and we’d rather keep it KISS than have rare state sync issues.
            //
            // In the original @dotlottie/player-component implementation, controls were implemented inside Lottie,
            // and they subscribed directly to Lottie’s internal state store. We don’t have that luxury :(
            const syncState = () => {
                const dotLottie = getDotLottie()
                if (dotLottie) {
                    setIsPlaying(Boolean(dotLottie.isPlaying))
                    setIsLooping(Boolean(dotLottie.loop))
                    setProgress(getProgressFromDotLottie(dotLottie))
                }

                frameId = requestAnimationFrame(syncState)
            }

            syncState()

            return () => {
                cancelAnimationFrame(frameId)
            }
        }, [props.dotLottie, props.src])

        function handleTogglePlay() {
            const dotLottie = getDotLottie()
            if (!dotLottie) return

            if (dotLottie.isPlaying) {
                dotLottie.pause()
            } else {
                dotLottie.play()
            }
        }

        function handleSeek(nextProgress) {
            const dotLottie = getDotLottie()
            setProgress(nextProgress)

            if (!dotLottie?.totalFrames) return

            dotLottie.setFrame((nextProgress / 100) * dotLottie.totalFrames)
        }

        function handleSeekStart() {
            getDotLottie()?.freeze?.()
        }

        function handleSeekEnd() {
            getDotLottie()?.unfreeze?.()
        }

        function handleToggleLoop() {
            const nextLooping = !isLooping

            setIsLooping(nextLooping)
            getDotLottie()?.setLoop(nextLooping)
        }

        return (
            <motion.div
                id="lottie-controls"
                aria-label="lottie-animation-controls"
                className="dotlottie-controls"
                initial={{ opacity: props.initialIsVisible ? 1 : 0 }}
                animate={{ opacity: props.isVisible ? 1 : 0 }}
                transition={{ duration: 0.2 }}
            >
                <button
                    id="lottie-play-button"
                    type="button"
                    aria-label="play / pause animation"
                    className={[
                        "dotlottie-controls__button",
                        "dotlottie-controls__button--play",
                        isPlaying && "dotlottie-controls__button--active",
                    ]
                        .filter(Boolean)
                        .join(" ")}
                    onClick={handleTogglePlay}
                >
                    {isPlaying ? <PauseIcon /> : <PlayIcon />}
                </button>
                <input
                    id="lottie-seeker-input"
                    type="range"
                    min="0"
                    step="1"
                    max="100"
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-valuenow={progress}
                    aria-label="lottie-seek-input"
                    role="slider"
                    className={[
                        "dotlottie-controls__seeker",
                        isReverse && "dotlottie-controls__seeker--reverse",
                    ]
                        .filter(Boolean)
                        .join(" ")}
                    style={{ "--seeker": progress } as React.CSSProperties}
                    value={progress}
                    onInput={(event: React.FormEvent<HTMLInputElement>) =>
                        handleSeek(Number(event.currentTarget.value))
                    }
                    onMouseDown={handleSeekStart}
                    onMouseUp={handleSeekEnd}
                    onTouchStart={handleSeekStart}
                    onTouchEnd={handleSeekEnd}
                />
                <button
                    id="lottie-loop-toggle"
                    type="button"
                    aria-label="loop-toggle"
                    className={[
                        "dotlottie-controls__button",
                        "dotlottie-controls__button--loop",
                        isLooping && "dotlottie-controls__button--active",
                    ]
                        .filter(Boolean)
                        .join(" ")}
                    onClick={handleToggleLoop}
                >
                    <LoopIcon />
                </button>
            </motion.div>
        )
    },
    [
        `.dotlottie-controls { --lottie-player-toolbar-height: 35px; --lottie-player-toolbar-background-color: transparent; --lottie-player-toolbar-hover-background-color: #f3f6f8; --lottie-player-toolbar-icon-color: #20272c; --lottie-player-toolbar-icon-hover-color: #f3f6f8; --lottie-player-toolbar-icon-active-color: #00ddb3; --lottie-player-seeker-track-color: #00ddb3; --lottie-player-seeker-accent-color: #00c1a2; --lottie-player-seeker-thumb-color: #00c1a2; display: flex; place-items: center; background-color: var(--lottie-player-toolbar-background-color); margin: 0 8px; height: var(--lottie-player-toolbar-height); font-family: Karla, sans-serif; font-style: normal; -webkit-font-smoothing: antialiased; }`,
        `.dotlottie-controls * { box-sizing: border-box; }`,
        `.dotlottie-controls__button { color: var(--lottie-player-toolbar-icon-color); cursor: pointer; display: flex; background: none; border: 0; border-radius: 4px; padding: 4px; outline: none; width: 24px; height: 24px; align-items: center; justify-content: center; flex: 0 0 auto; }`,
        `.dotlottie-controls__button:hover { background-color: var(--lottie-player-toolbar-icon-hover-color); }`,
        `.dotlottie-controls__button:focus-visible { outline: 2px solid var(--lottie-player-toolbar-icon-active-color); }`,
        `.dotlottie-controls__button--active { color: var(--lottie-player-toolbar-icon-active-color); }`,
        `.dotlottie-controls__button--play { margin-right: 8px;margin-left: 4px; }`,
        `.dotlottie-controls__button--loop { margin-right: 4px; margin-left: 8px; }`,
        `.dotlottie-controls__button--disabled, .dotlottie-controls__button:disabled { opacity: 0.45; cursor: not-allowed; }`,
        `.dotlottie-controls__button svg { width: 16px; height: 16px; }`,
        `.dotlottie-controls__seeker { height: 4px; width: 100%; min-width: 0; outline: none; appearance: none; border-radius: 9999px; cursor: pointer; background-image: linear-gradient(to right,rgb(0, 221, 179) calc(var(--seeker) * 1%),rgb(217, 224, 230) calc(var(--seeker) * 1%)); }`,
        `.dotlottie-controls__seeker--reverse { background-image: linear-gradient(to right,rgb(217, 224, 230) calc(var(--seeker) * 1%),rgb(0, 221, 179) calc(var(--seeker) * 1%)); }`,
        `.dotlottie-controls__seeker::-webkit-slider-runnable-track { width: 100%; height: 5px; cursor: pointer; }`,
        `.dotlottie-controls__seeker::-webkit-slider-thumb { appearance: none; height: 16px; width: 16px; border-radius: 50%; background: var(--lottie-player-seeker-thumb-color); cursor: pointer; margin-top: -5px; }`,
        `.dotlottie-controls__seeker:focus-visible::-webkit-slider-thumb { outline: 2px solid var(--lottie-player-seeker-track-color); border: 1.5px solid rgb(255, 255, 255); }`,
        `.dotlottie-controls__seeker::-webkit-slider-thumb:hover { background: rgb(1, 157, 145); }`,
    ],
    "framer-dot-lottie-controls"
)

export default LottieControls
